import{_ as s,l as o,o as e,c as l,v as r,p as n,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ABR 自适应码率","description":"","frontmatter":{"title":"ABR 自适应码率","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/abr-streaming.md","filePath":"cs/abr-streaming.md","lastUpdated":1789023840000}'),c={name:"cs/abr-streaming.md"};function B(_,a,m,A,E,u){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="abr-自适应码率" tabindex="-1">ABR 自适应码率 <a class="header-anchor" href="#abr-自适应码率" aria-label="Permalink to &quot;ABR 自适应码率&quot;">​</a></h1><div class="epigraph"><p>播放器根据吞吐估计与缓冲水位在阶梯码率间切换，逼近瞬时可用带宽，避免卡顿或无谓的 4K。</p><footer>—— 据 Huang et al. 缓冲基 ABR；DASH/HLS 实践；Kurose 多媒体节整理</footer></div><p><a href="/cs/dash-hls">DASH/HLS</a> 提供阶梯。<a href="/cs/mimo-rate-adaptation">速率自适应</a> 在 Wi‑Fi PHY。<a href="/cs/dash-hls">上一课</a> 留下选哪一档。缺口是 <strong>ABR 控制</strong>：吞吐估计、缓冲、振荡。本课不把 CDN 层次写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可用带宽随 Wi‑Fi、蜂窝、同屋流变化。固定高码率则再缓冲；固定低则浪费 \\(C\\)。ABR：测最近分片吞吐，看缓冲秒数，选下一表示。过敏则码率振荡（视觉差），过钝则卡。与 TCP CC 叠：ABR 在应用，CUBIC 在运输，双环。BBR 下估计更稳或仍抖，取决于实现。</p><p>不要把 ABR 写成 5G 切片保证。</p><p><span class="marginnote">缓冲基（BBA）等算法。本课不点名商业播放器。</span></p><h3 id="应用层跟踪可用带宽" tabindex="-1">应用层跟踪可用带宽 <a class="header-anchor" href="#应用层跟踪可用带宽" aria-label="Permalink to &quot;应用层跟踪可用带宽&quot;">​</a></h3><p>与 TCP/BBR 双环，要滤波防振荡。令牌桶边缘限速会表现为「网慢」。清单缺中间档则跳变。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：基于吞吐 / 基于缓冲 / 混合。画：下片 → 估 BW → 选档。与令牌桶：边缘限速会让 ABR 降档，表现为「网很慢」。</p>',11)),(e(),n(p,null,{default:t(()=>[h(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20THR%5B%22%E5%88%86%E7%89%87%E5%90%9E%E5%90%90%22%5D%20--%3E%20DEC%5B%22%E9%80%89%E7%A0%81%E7%8E%87%22%5D%0A%20%20BUF%5B%22%E7%BC%93%E5%86%B2%E6%B0%B4%E4%BD%8D%22%5D%20--%3E%20DEC%0A%20%20DEC%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E5%88%86%E7%89%87%20GET%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CDN 不同 POP 吞吐不同，切换 POP 像路径变。ECN 膨胀影响估计。QUIC 迁移换路要重新估计。无线 TCP 误码让吞吐锯齿，ABR 应滤波。与 WFQ：隔离后估计更干净。</p><p>安全：恶意慢片可诱骗降档，点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入强化学习 ABR 的全部。CDN 缓存层次与失效是下一课。后课默认：ABR 是应用层对可用带宽的阶梯跟踪。</p><p>清单若缺中间档，控制再好也跳变。</p><p>上一课留下的缺口在本课收口；「ABR 自适应码率」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/cdn-cache-hierarchy">CDN 缓存层次与失效</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>吞吐与缓冲驱动选档。</li><li>与 TCP/BBR 形成双环，要滤波。</li><li>目标是卡顿与质量折中，不是峰值码率。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ABR 文献；DASH/HLS 实践。</li></ul>',10))])}const P=s(c,[["render",B]]);export{f as __pageData,P as default};
